import{_ as a,C as r,o as l,c as s,a2 as o,E as e}from"./chunks/framework.COkhqeFn.js";const Q=JSON.parse('{"title":"QUB核心 (QUB) - QUB Core","description":"","frontmatter":{},"headers":[],"relativePath":"projects/QUB核心_QUB_QUBCore.md","filePath":"projects/QUB核心_QUB_QUBCore.md"}'),d={name:"projects/QUB核心_QUB_QUBCore.md"};function h(g,t,c,U,u,_){const i=r("ExchangePrice"),n=r("GitHubStats");return l(),s("div",null,[t[0]||(t[0]=o('<h1 id="qub核心-qub-qub-core" tabindex="-1">QUB核心 (QUB) - QUB Core <a class="header-anchor" href="#qub核心-qub-qub-core" aria-label="Permalink to &quot;QUB核心 (QUB) - QUB Core&quot;">​</a></h1><ul><li><strong>论坛:</strong> [ANN] QUB Core: A PoW Blockchain Built in Rust (No EVM, Native Multi-Asset UTXO)</li><li><strong>发布者:</strong> xProe</li><li><strong>创建日期:</strong> 2026-06-03</li><li><strong>最后活动:</strong> 2026-06-03</li><li><strong>回复数:</strong> 0</li><li><strong>浏览量:</strong> 0</li><li><strong>状态:</strong> 主网已上线</li></ul>',2)),e(i,{ticker:"QUB"}),t[1]||(t[1]=o('<h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h2><p>QUB Core 是一个从头用 Rust 编写的非 EVM、UTXO 模型的 CPU/GPU PoW 区块链，包含全节点、钱包、矿工、矿池、同步/修复、内存池和多资产功能。项目由 Alexander Proestakis 发起，旨在构建一个简洁的挖矿层，连接到 JIN 和 Enjin Matrixchain 生态系统的更深层价值。</p><p>QUB 采用双资产架构：QUB 作为可挖矿的外层，JIN 作为价值层（通缩供应 1.05 亿枚），而 ENJ 作为 Matrixchain 上的深层价值已注入 JIN（约 70 万 ENJ 已注入）。未来计划通过桥接实现 QUB 上的 JIN Coin 和 Enjin Matrixchain 上的 JIN Token 1:1 兑换。</p><h2 id="技术参数" tabindex="-1">技术参数 <a class="header-anchor" href="#技术参数" aria-label="Permalink to &quot;技术参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td>代币</td><td>QUB</td></tr><tr><td>共识机制</td><td>PoW（工作量证明）</td></tr><tr><td>挖矿设备</td><td>CPU + OpenCL GPU</td></tr><tr><td>开发语言</td><td>Rust</td></tr><tr><td>UTXO 模型</td><td>原生多资产 UTXO</td></tr><tr><td>虚拟机</td><td>非 EVM</td></tr><tr><td>许可证</td><td>Apache License 2.0</td></tr><tr><td>治理</td><td>Verified Governance v1（预定区块 #21000 激活）</td></tr><tr><td>当前版本</td><td>QUB Core v1.7.0 HF110</td></tr></tbody></table><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><ul><li><strong>全节点</strong>: Rust QUB 节点，含同步/修复/自愈逻辑</li><li><strong>挖矿</strong>: 支持 CPU 挖矿、OpenCL GPU 挖矿、单挖和矿池挖矿</li><li><strong>钱包</strong>: 完整钱包和地址管理工具</li><li><strong>内存池和区块验证</strong>: 完整的内存池和区块验证逻辑</li><li><strong>JIN 支持</strong>: 原生 JIN 支持，显示 JIN 余额、发送和交易活动</li><li><strong>多资产 UTXO</strong>: 原生多资产支持</li><li><strong>QNS</strong>: QUB Name System</li><li><strong>稳定币 UI</strong>: 稳定币界面和以太坊合约支持脚手架</li><li><strong>主网已上线</strong>: 当前最新下载版本 QUB Core v1.2.0（Windows x64）</li></ul><h2 id="经济模型" tabindex="-1">经济模型 <a class="header-anchor" href="#经济模型" aria-label="Permalink to &quot;经济模型&quot;">​</a></h2><ul><li><strong>QUB</strong>: 可挖矿的外层代币，通过区块奖励保护网络</li><li><strong>JIN</strong>: 价值层代币，通缩供应 1.05 亿枚，可通过熔解 QUB 回收</li><li><strong>ENJ</strong>: Enjin Matrixchain 深层价值，约 70 万 ENJ 已注入 JIN</li></ul><h2 id="项目架构" tabindex="-1">项目架构 <a class="header-anchor" href="#项目架构" aria-label="Permalink to &quot;项目架构&quot;">​</a></h2><p>QUB 被设计为多层价值连接器：</p><ol><li><strong>挖 QUB</strong> — 用户通过 CPU/GPU 挖矿获得 QUB</li><li><strong>QUB 承载 JIN 价值</strong> — QUB 内部可注入持有 JIN 价值</li><li><strong>JIN 连接 Enjin Matrixchain</strong> — 未来 1:1 桥接 QUB 上的 JIN Coin 和 Matrixchain 上的 JIN Token</li><li><strong>JIN 携带 ENJ 深度</strong> — JIN Token 已有 ENJ 注入缓冲，QUB 成为面向用户的简单挖矿层间接连接 ENJ</li></ol><h2 id="链接" tabindex="-1">链接 <a class="header-anchor" href="#链接" aria-label="Permalink to &quot;链接&quot;">​</a></h2><ul><li><strong>官网:</strong> <a href="https://download.qubit-coin.io/" target="_blank" rel="noreferrer">https://download.qubit-coin.io/</a></li><li><strong>GitHub:</strong> <a href="https://github.com/AlxProe/qub-core" target="_blank" rel="noreferrer">https://github.com/AlxProe/qub-core</a></li><li><strong>论坛主题:</strong> <a href="https://bitcointalk.org/index.php?topic=5584743.0" target="_blank" rel="noreferrer">https://bitcointalk.org/index.php?topic=5584743.0</a></li></ul>',14)),e(n,{repo:"AlxProe/qub-core"})])}const b=a(d,[["render",h]]);export{Q as __pageData,b as default};
